from pathlib import Path
from datetime import datetime
import base64, re, shutil

ROOT=Path.cwd()
REQUIRED=[ROOT/'src/scoring/research_scoring.py',ROOT/'src/enrichment/profiles.py',ROOT/'src/enrichment/consultation_schedule.py',ROOT/'src/enrichment/safe_web.py',ROOT/'src/enrichment/kouseikyoku_source.py']
missing=[str(p) for p in REQUIRED if not p.exists()]
if missing:
    print('エラー：clinic-list-filter-complete のフォルダで実行してください。')
    print('見つからないファイル:')
    [print(' -',p) for p in missing]
    raise SystemExit(1)

stamp=datetime.now().strftime('%Y%m%d_%H%M%S')
backup=ROOT/f'code_backup_research_v22_{stamp}'
backup.mkdir(parents=True,exist_ok=False)
for p in REQUIRED:
    rel=p.relative_to(ROOT); dst=backup/rel; dst.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,dst)

PAYLOADS={'src/scoring/research_scoring.py': '', 'src/enrichment/profiles.py': '', 'src/enrichment/consultation_schedule.py': '', 'export_research_v22_results.py': ''}
for rel,data in PAYLOADS.items():
    path=ROOT/rel; path.parent.mkdir(parents=True,exist_ok=True); path.write_bytes(base64.b64decode(data))

safe=ROOT/'src/enrichment/safe_web.py'
s=safe.read_text(encoding='utf-8')
priority='PRIORITY = re.compile(r"内視鏡|白内障|緑内障|治療|手術|検査|処置|料金|費用|院長|医師紹介|経歴|略歴|医院紹介|診療時間|受付時間|診療|自費|予約|doctor|staff|profile|career|schedule|hours|treatment|endoscop|cataract|glaucoma|medical|price|fee|access|about|clinic|lp/",re.I)'
new_s,n=re.subn(r'^PRIORITY\s*=\s*re\.compile\(.*?\)$',lambda m: priority,s,count=1,flags=re.M)
if n!=1:
    print('エラー：safe_web.py の PRIORITY 行を確認できません。変更を元に戻して停止します。')
    for p in REQUIRED: rel=p.relative_to(ROOT); shutil.copy2(backup/rel,p)
    raise SystemExit(1)
safe.write_text(new_s,encoding='utf-8')

k=ROOT/'src/enrichment/kouseikyoku_source.py'
s=k.read_text(encoding='utf-8')
if '"manager_age":' not in s:
    marker='    "designation_date": ["designation_date", "指定年月日"],\n'
    insert='    "designation_date": ["designation_date", "指定年月日"],\n    "manager_age": ["manager_age", "管理者年齢", "院長年齢"],\n    "manager_birth_year": ["manager_birth_year", "管理者生年", "院長生年"],\n    "license_registration_year": ["license_registration_year", "医籍登録年", "医師免許取得年"],\n    "graduation_year": ["graduation_year", "大学卒業年", "医学部卒業年"],\n'
    if marker not in s:
        print('エラー：kouseikyoku_source.py の指定年月日定義を確認できません。変更を元に戻して停止します。')
        for p in REQUIRED: rel=p.relative_to(ROOT); shutil.copy2(backup/rel,p)
        raise SystemExit(1)
    s=s.replace(marker,insert,1)
k.write_text(s,encoding='utf-8')
(ROOT/'VERSION_RESEARCH').write_text('2.2-research\n',encoding='utf-8')

print('修正しました。')
print('・治療カテゴリ：医院名 → HOME/医院紹介の治療タブ → 独立治療ページの順で判定。本文だけの単語はカテゴリにしません。')
print('・医院名に治療名がある場合は treatment_name_hot=True として最優先根拠を保存します。')
print('・年齢：厚生局の年齢関連項目を先に確認。指定年月日は開業根拠として確認し、年齢を直接作らず院長経歴の卒業年/医籍年へフォールバックします。')
print('・集客施策：トップページ下部、左右/固定バナー、画像alt、外部媒体/SNS/LINE/AIチャット等のリンクを重点確認します。')
print('・昼枠：診療時間表だけから午前→検査/手術/処置→午後を判定し、★=手術等の凡例にも対応します。')
print('・既存SQLite、UUID、Google Maps結果、Comdesk元行は変更していません。')
print('・比較用出力: export_research_v22_results.py')
print('バックアップ:',backup.name)
